class Auth{constructor(){this.token=null,this.user=null}async validate(){try{const t=window.Telegram.WebApp,e=t.initData;if(console.log("Auth: Starting validation..."),console.log("Auth: Telegram WebApp version:",t.version),console.log("Auth: initData length:",e?e.length:0),console.log("Auth: initData preview:",e?e.substring(0,100)+"...":"EMPTY"),!e)return console.error("Auth: initData is empty - WebApp not launched from Telegram?"),alert("Ошибка: initData пустой. Откройте WebApp через Telegram бота."),!1;console.log("Auth: Calling /api/v1/webapp/validate...");const o=await fetch("/api/v1/webapp/validate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({initData:e})});if(console.log("Auth: Response status:",o.status),!o.ok){const t=await o.text();return console.error("Auth: Validation failed",o.status,t),alert(`Ошибка авторизации: ${o.status}\n${t}`),!1}const a=await o.json();return console.log("Auth: Validation successful, user:",a.user),this.token=a.access_token,this.user=a.user,await this.saveTokenToStorage(),!0}catch(t){return console.error("Auth: Validation error",t),alert(`Ошибка инициализации: ${t.message}`),!1}}async saveTokenToStorage(){if(this.token)try{await new Promise(((t,e)=>{window.Telegram.WebApp.CloudStorage.setItem("access_token",this.token,((o,a)=>{o?e(o):t(a)}))}))}catch(t){console.error("Auth: Failed to save token to storage",t)}}async loadTokenFromStorage(){try{const t=await new Promise(((t,e)=>{window.Telegram.WebApp.CloudStorage.getItem("access_token",((o,a)=>{o?e(o):t(a)}))}));return t?(this.token=t,t):null}catch(t){return console.error("Auth: Failed to load token from storage",t),null}}getToken(){return this.token}getUser(){return this.user}isAuthenticated(){return null!==this.token}}